from pathlib import Path
from lfx.custom.custom_component.component import Component
from lfx.io import MessageTextInput, Output
from lfx.schema.message import Message


class ReadFile(Component):
    display_name = "Read File"
    description = "Reads a local text or document file."
    icon = "file-text"
    name = "ReadFile"

    inputs = [
        MessageTextInput(
            name="file_path",
            display_name="File Path",
            value="",
            info="Absolute path to the text file.",
            required=True,
        )
    ]
    outputs = [
        Output(display_name="Content", name="message", method="read_file")
    ]

    def read_file(self) -> Message:
        p = Path(self.file_path)
        if not p.exists():
            return Message(text=f"File not found: {self.file_path}")
        try:
            return Message(text=p.read_text(encoding="utf-8", errors="ignore"))
        except Exception as e:
            return Message(text=f"Error reading file: {str(e)}")

